def find_peak(arr, n):
    # Initialize the first element as the peak
    peak = arr[0]
    # Iterate through the array starting from the second element
    for i in range(1, n):
        # Check if the current element is greater than the peak
        if arr[i] > peak:
            peak = arr[i]
    return peak

def add_pairwise(tup):
    # Initialize an empty list to store the pairwise sums
    pairwise_sums = []
    # Iterate through the tuple and calculate the sum of each pair
    for i in range(len(tup)):
        for j in range(i + 1, len(tup)):
            pairwise_sums.append(tup[i] + tup[j])
    # Return the list of pairwise sums
    return pairwise_sums

def check_Consecutive(lst):
    # Check if the list is empty
    if not lst:
        return False
    # Iterate through the list and check if each element is consecutive
    for i in range(1, len(lst)):
        if lst[i] - lst[i-1] != 1:
            return False
    return True

