def big_sum(arr):
    # Initialize max and min with the first element of the array
    max = arr[0]
    min = arr[0]

    # Iterate through the array to find the maximum and minimum values
    for i in arr:
        if i > max:
            max = i
        if i < min:
            min = i

    # Return the sum of the largest and smallest values
    return max + min

