def get_max_occuring_char(s):
    # Create a dictionary to count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    # Find the maximum occurrence character
    max_char = max(char_count, key=char_count.get)
    return max_char

