code:
def gcd(a, b):
    # Ensure a is the smaller number
    if a > b:
        a, b = b, a
    # Loop until b becomes 0
    while b != 0:
        # Replace a with b and b with a % b
        a, b = b, a % b
    # The gcd is now a
    return a

def permutation_coefficient(n, k):
    # Base case: if k is 0 or n is 0, the coefficient is 1
    if k == 0 or n == 0:
        return 1
    # Recursive case: calculate the permutation coefficient
    return n * permutation_coefficient(n-1, k-1)

